// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListCycles The user's cycles with their goal and training counts, the latest first.
	// (GET /cycles)
	ListCycles(ctx context.Context, request ListCyclesRequestObject) (ListCyclesResponseObject, error)

	// (POST /cycles)
	CreateCycle(ctx context.Context, request CreateCycleRequestObject) (CreateCycleResponseObject, error)
	// ImportCycle Save a whole cycle with its trainings at once, or nothing if any part is invalid (body up to 8 MiB).
	// (POST /cycles/import)
	ImportCycle(ctx context.Context, request ImportCycleRequestObject) (ImportCycleResponseObject, error)
	// DeleteCycle Soft-delete a cycle; its trainings leave it (keep) or are deleted too.
	// (DELETE /cycles/{id})
	DeleteCycle(ctx context.Context, request DeleteCycleRequestObject) (DeleteCycleResponseObject, error)

	// (GET /cycles/{id})
	GetCycle(ctx context.Context, request GetCycleRequestObject) (GetCycleResponseObject, error)

	// (PUT /cycles/{id})
	UpdateCycle(ctx context.Context, request UpdateCycleRequestObject) (UpdateCycleResponseObject, error)
	// ListSessions The user's session templates with their size.
	// (GET /sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)

	// (POST /sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)

	// (DELETE /sessions/{id})
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)

	// (GET /sessions/{id})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// UpdateSession Replace a template; trainings keep their copies.
	// (PUT /sessions/{id})
	UpdateSession(ctx context.Context, request UpdateSessionRequestObject) (UpdateSessionResponseObject, error)
	// ListTrainings The user's trainings with their size.
	// (GET /trainings)
	ListTrainings(ctx context.Context, request ListTrainingsRequestObject) (ListTrainingsResponseObject, error)

	// (POST /trainings)
	CreateTraining(ctx context.Context, request CreateTrainingRequestObject) (CreateTrainingResponseObject, error)

	// (DELETE /trainings/{id})
	DeleteTraining(ctx context.Context, request DeleteTrainingRequestObject) (DeleteTrainingResponseObject, error)

	// (GET /trainings/{id})
	GetTraining(ctx context.Context, request GetTrainingRequestObject) (GetTrainingResponseObject, error)

	// (PUT /trainings/{id})
	UpdateTraining(ctx context.Context, request UpdateTrainingRequestObject) (UpdateTrainingResponseObject, error)
	// DuplicateTraining Copy a training (inactive) as the next phase, starting the Monday after it ends.
	// (POST /trainings/{id}/duplicate)
	DuplicateTraining(ctx context.Context, request DuplicateTrainingRequestObject) (DuplicateTrainingResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

